import AppKit

/// The Clip tab's TEXT sections (spec §4.3): content, face, colour,
/// alignment, spacing, outline, backdrop, the box mode, how the words arrive
/// and leave, and the four presets.
///
/// **This pane is never shown**: since the six tabs became three it is a
/// factory `ClipPane` holds and calls, right after Transform, when EVERY
/// selected clip is a text clip. Shadow is not in the list any more — it is
/// one field (`video.shadow`) shared with the video and shape sections, so the
/// Clip tab carries it once, in the effects group.
///
/// The model stores ONE font string — a PostScript name (§5.2's
/// `"SourceSans3-SemiBold"`) — while the panel offers the two popups people
/// expect, family and style. `TextFace` is the whole translation between
/// them, and it is deliberately tolerant: a project made on another machine
/// can name a face this one does not have, and the pane must still open.
final class TextPane: InspectorPaneView {
    /// Whether the text sections apply: they write `set_text`, which errors on
    /// any other kind, so a mixed selection gets none of them.
    var allText: Bool {
        !binding.clips.isEmpty && binding.textClips.count == binding.clips.count
    }

    /// A family change replaces the style popup's ITEMS, so it has to be part
    /// of the rebuild signature — refreshing alone would leave the old
    /// family's styles listed.
    override var structureSignature: String {
        super.structureSignature + "|" + TextFace.family(of: binding.textProps.font)
    }

    // MARK: Content

    /// The footnote on a word-styled page whose timings a content edit
    /// dropped (road map 8 §5e), and the Animation section's on a styled
    /// page, whose reveal the word style replaces (spec §11 W-5). The second
    /// is short on purpose: its row is 244 pt at the 280 pt narrowest
    /// inspector (`DocumentPane.transparencyNote` has the arithmetic, #70).
    static let untimedNote = "Not timed — regenerate to time it again"
    static let wordStyleNote = "Word style wins; the reveal does not apply."

    func contentSection() -> InspectorSection {
        let binding = self.binding
        let area = InspectorTextArea(
            read: { binding.textProps.content },
            // Per clip: a timed page keeps its words while the count holds
            // and sends `words: []` beside the content when it does not.
            write: { value in binding.apply("Edit Text", binding.ops(textContent: value)) },
            enabled: { !binding.textClips.isEmpty },
            onEdit: { binding.edited() })
        return InspectorSection(
            id: "text.content", title: "Content",
            summary: {
                let line = binding.textProps.content
                    .split(whereSeparator: \.isNewline).first.map(String.init) ?? ""
                return line.isEmpty ? "empty" : line
            },
            note: {
                binding.textProps.isUntimedPage ? Self.untimedNote : nil
            },
            rows: [inspectorRow(nil, [area], binding: binding,
                                writes: binding.ops(textContent: binding.textProps.content),
                                discrete: true)])
    }

    // MARK: Face

    func fontSection() -> InspectorSection {
        let binding = self.binding
        let families = TextFace.families
        let family = TextFace.family(of: binding.textProps.font)
        let members = TextFace.members(of: family)
        let font = binding.ops(text: TextPatch(font: binding.textProps.font))

        let familyPopup = OptionPopupControl(
            width: 150, items: families,
            read: { families.firstIndex(of: TextFace.family(of: binding.textProps.font)) ?? 0 },
            write: { index in
                guard families.indices.contains(index) else { return }
                let current = binding.textProps.font
                let name = TextFace.postScriptName(
                    family: families[index], style: TextFace.style(of: current))
                binding.apply("Font", text: TextPatch(font: name))
            },
            enabled: { true },
            onEdit: { binding.edited() })

        let stylePopup = OptionPopupControl(
            width: 116, items: members.map { $0.style },
            read: {
                let name = binding.textProps.font
                return members.firstIndex { $0.name == name } ?? 0
            },
            write: { index in
                guard members.indices.contains(index) else { return }
                binding.apply("Font", text: TextPatch(font: members[index].name))
            },
            enabled: { !members.isEmpty },
            onEdit: { binding.edited() })

        return InspectorSection(
            id: "text.font", title: "Font",
            summary: { String(format: "%.0f px", binding.textProps.size) },
            defaultExpanded: false,
            rows: [
                inspectorRow(
                    "Family", [familyPopup], mixed: { binding.mixedText { $0.font } },
                    binding: binding, writes: font),
                inspectorRow("Style", [stylePopup], binding: binding, writes: font),
                inspectorValueRow(
                    "Size", binding, name: "Font Size", unit: " px", decimals: 0, min: 6,
                    max: 800, quick: [24, 36, 48, 72, 96, 144], slider: false,
                    read: { binding.textProps.size },
                    ops: { binding.ops(text: TextPatch(size: $0)) },
                    mixed: { binding.mixedText { $0.size } }),
            ])
    }

    // MARK: Style

    func styleSection() -> InspectorSection {
        let binding = self.binding
        let aligns = ["left", "center", "right"]
        let valigns = ["top", "middle", "bottom"]
        let text = binding.textProps
        let align = OptionSegmentedControl(
            segments: [
                ("text.alignleft", "L", "Align left"),
                ("text.aligncenter", "C", "Align center"),
                ("text.alignright", "R", "Align right"),
            ],
            read: { aligns.firstIndex(of: binding.textProps.align) ?? 1 },
            write: { index in
                guard aligns.indices.contains(index) else { return }
                binding.apply("Alignment", text: TextPatch(align: aligns[index]))
            },
            segmentEnabled: nil, enabled: { true },
            onEdit: { binding.edited() })
        let valign = OptionSegmentedControl(
            segments: [
                ("align.vertical.top", "⤒", "Align to the top of the box"),
                ("align.vertical.center", "↕", "Center in the box"),
                ("align.vertical.bottom", "⤓", "Align to the bottom of the box"),
            ],
            read: { valigns.firstIndex(of: binding.textProps.valign) ?? 1 },
            write: { index in
                guard valigns.indices.contains(index) else { return }
                binding.apply("Alignment", text: TextPatch(valign: valigns[index]))
            },
            segmentEnabled: nil, enabled: { true },
            onEdit: { binding.edited() })

        return InspectorSection(
            id: "text.style", title: "Style",
            summary: { binding.textProps.align },
            reset: {
                let defaults = TextProps()
                binding.apply(
                    "Text Style",
                    text: TextPatch(
                        color: defaults.color, align: defaults.align, valign: defaults.valign,
                        lineSpacing: defaults.lineSpacing, tracking: defaults.tracking,
                        textCase: defaults.textCase))
            },
            defaultExpanded: false,
            rows: [
                inspectorColorRow(
                    "Color", binding, name: "Text Color", read: { binding.textProps.color },
                    ops: { binding.ops(text: TextPatch(color: $0)) },
                    mixed: { binding.mixedText { $0.color } }),
                inspectorRow("Align", [align], mixed: { binding.mixedText { $0.align } },
                    binding: binding, writes: binding.ops(text: TextPatch(align: text.align)),
                    default: .derived(binding, name: "Alignment", read: { binding.textProps.align },
                                      ops: { binding.ops(text: TextPatch(align: $0)) })),
                inspectorRow("Vertical", [valign], mixed: { binding.mixedText { $0.valign } },
                    binding: binding, writes: binding.ops(text: TextPatch(valign: text.valign)),
                    default: .derived(
                        binding, name: "Alignment", read: { binding.textProps.valign },
                        ops: { binding.ops(text: TextPatch(valign: $0)) })),
                inspectorCheckRow(
                    "UPPERCASE", binding, name: "Case",
                    read: { binding.textProps.textCase == .upper },
                    ops: { binding.ops(text: TextPatch(textCase: $0 ? .upper : .asWritten)) },
                    mixed: { binding.mixedText { $0.textCase } }),
                inspectorValueRow(
                    "Line spacing", binding, name: "Line Spacing", unit: "×", decimals: 2,
                    min: 0.5, max: 4,
                    read: { binding.textProps.lineSpacing },
                    ops: { binding.ops(text: TextPatch(lineSpacing: $0)) },
                    mixed: { binding.mixedText { $0.lineSpacing } }),
                inspectorValueRow(
                    "Tracking", binding, name: "Tracking", unit: " px", decimals: 1, min: -20,
                    max: 100,
                    read: { binding.textProps.tracking },
                    ops: { binding.ops(text: TextPatch(tracking: $0)) },
                    mixed: { binding.mixedText { $0.tracking } }),
            ])
    }

    // MARK: Outline

    func outlineSection() -> InspectorSection {
        let binding = self.binding
        func current() -> OutlineProps { binding.textProps.outline ?? OutlineProps() }
        func on() -> Bool { binding.textProps.outline != nil }
        return InspectorSection(
            id: "text.outline", title: "Outline",
            summary: { on() ? String(format: "%.1f px", current().width) : "off" },
            reset: { binding.apply("Outline", text: TextPatch(outline: .some(nil))) },
            defaultExpanded: false,
            rows: [
                inspectorCheckRow(
                    "Outline", binding, name: "Outline", read: on,
                    ops: { value in
                        binding.ops(
                            text: TextPatch(outline: value ? .some(OutlineProps()) : .some(nil)))
                    },
                    mixed: { binding.mixedText { $0.outline != nil } }),
                inspectorValueRow(
                    "Width", binding, name: "Outline Width", unit: " px", decimals: 1, min: 0,
                    max: 40, quick: [1, 2, 4, 8],
                    read: { current().width },
                    ops: { value in
                        var o = current()
                        o.width = value
                        return binding.ops(text: TextPatch(outline: .some(o)))
                    },
                    mixed: { binding.mixedText { $0.outline?.width } },
                    enabled: on),
                inspectorColorRow(
                    "Color", binding, name: "Outline Color", read: { current().color },
                    ops: { color in
                        var o = current()
                        o.color = color
                        return binding.ops(text: TextPatch(outline: .some(o)))
                    },
                    mixed: { binding.mixedText { $0.outline?.color } },
                    enabled: on),
            ])
    }

    // MARK: Backdrop

    func backdropSection() -> InspectorSection {
        let binding = self.binding
        func current() -> BackdropProps { binding.textProps.backdrop ?? BackdropProps() }
        func on() -> Bool { binding.textProps.backdrop != nil }
        func ops(_ next: BackdropProps) -> [ReelOp] {
            binding.ops(text: TextPatch(backdrop: .some(next)))
        }
        return InspectorSection(
            id: "text.backdrop", title: "Backdrop",
            summary: { on() ? String(format: "%.0f px", current().padding) : "off" },
            reset: { binding.apply("Backdrop", text: TextPatch(backdrop: .some(nil))) },
            defaultExpanded: false,
            rows: [
                inspectorCheckRow(
                    "Backdrop", binding, name: "Backdrop", read: on,
                    ops: { value in
                        binding.ops(
                            text: TextPatch(backdrop: value ? .some(BackdropProps()) : .some(nil)))
                    },
                    mixed: { binding.mixedText { $0.backdrop != nil } }),
                inspectorColorRow(
                    "Fill", binding, name: "Backdrop Color", read: { current().color },
                    ops: { color in
                        var b = current()
                        b.color = color
                        return ops(b)
                    },
                    mixed: { binding.mixedText { $0.backdrop?.color } },
                    enabled: on),
                inspectorValueRow(
                    "Padding", binding, name: "Backdrop Padding", unit: " px", decimals: 0,
                    min: 0, max: 200, quick: [0, 8, 12, 24, 48],
                    read: { current().padding },
                    ops: { value in
                        var b = current()
                        b.padding = value
                        return ops(b)
                    },
                    mixed: { binding.mixedText { $0.backdrop?.padding } },
                    enabled: on),
                inspectorValueRow(
                    "Radius", binding, name: "Backdrop Radius", unit: " px", decimals: 0, min: 0,
                    max: 200, quick: [0, 4, 8, 16, 32],
                    read: { current().radius },
                    ops: { value in
                        var b = current()
                        b.radius = value
                        return ops(b)
                    },
                    mixed: { binding.mixedText { $0.backdrop?.radius } },
                    enabled: on),
            ])
    }

    // MARK: Box

    /// Auto-size or a fixed width that wraps (§4.3). `width` is the model's
    /// three-state field: an explicit null restores auto-sizing, which is why
    /// the patch uses the double optional.
    func boxSection() -> InspectorSection {
        let binding = self.binding
        func fixed() -> Bool { binding.textProps.width != nil }
        func currentWidth() -> Double {
            binding.textProps.width ?? Double(binding.canvas.width) * 0.6
        }
        let mode = OptionPopupControl(
            width: 132, items: ["Auto-size", "Fixed width"],
            read: { fixed() ? 1 : 0 },
            write: { index in
                let patch = TextPatch(width: index == 1 ? .some(currentWidth()) : .some(nil))
                binding.apply("Text Box", text: patch)
            },
            enabled: { true },
            onEdit: { binding.edited() })
        return InspectorSection(
            id: "text.box", title: "Box",
            summary: { fixed() ? String(format: "%.0f px", currentWidth()) : "auto" },
            reset: { binding.apply("Text Box", text: TextPatch(width: .some(nil))) },
            defaultExpanded: false,
            rows: [
                inspectorRow("Mode", [mode], mixed: { binding.mixedText { $0.width != nil } },
                    binding: binding,
                    writes: binding.ops(text: TextPatch(width: .some(binding.textProps.width))),
                    default: .derived(binding, name: "Text Box", read: { binding.textProps.width },
                                      ops: { binding.ops(text: TextPatch(width: .some($0))) })),
                inspectorValueRow(
                    "Width", binding, name: "Text Width", unit: " px", decimals: 0, min: 20,
                    max: 20000, slider: false,
                    read: currentWidth,
                    ops: { binding.ops(text: TextPatch(width: .some($0))) },
                    mixed: { binding.mixedText { $0.width } },
                    enabled: fixed, resets: false),
            ])
    }

    // MARK: Animation

    /// How the words arrive and how they leave (§4.3, format version 5).
    ///
    /// Three controls for three keys: which reveal, how long it takes to
    /// arrive, and how long it takes to leave. The core turns them into one
    /// number per frame — nothing here draws or times anything, and the
    /// section cannot show the reveal's progress, because the progress is a
    /// fact about the frame under the playhead and not about the clip.
    ///
    /// `animation` is a whole OBJECT in the patch, so every row re-sends all
    /// three keys. The core MERGES a nested object key by key (§5.2), but a
    /// stored `null` is not an object — turning the reveal ON replaces the
    /// null with what this patch carries, and a key left out would then come
    /// from the struct's default and silently reset what the user did not
    /// touch. A section that knows all three keys is right in both cases.
    /// Turning the popup to None sends an explicit null, which is the
    /// model's "no animation".
    ///
    /// One thing worth knowing before animating this section from an action:
    /// `in` and `out` are numbers, so an action END patch would interpolate
    /// them and slide the animation's own timebase mid-reveal. The kind is a
    /// string and switches at the end, which is the sane half.
    func animationSection() -> InspectorSection {
        let binding = self.binding
        let kinds = TextAnimationKind.allCases
        let items = ["None"] + kinds.map { $0.displayName }
        func current() -> TextAnimation { binding.textProps.animation ?? TextAnimation() }
        func on() -> Bool { binding.textProps.animation != nil }
        func free() -> Bool { binding.textProps.wordStyle == nil }
        func ops(_ next: TextAnimation) -> [ReelOp] {
            binding.ops(text: TextPatch(animation: .some(next)))
        }
        return InspectorSection(
            id: "text.animation", title: "Reveal",
            summary: {
                guard let animation = binding.textProps.animation else { return "off" }
                return animation.kind.displayName.lowercased()
                    + String(format: " · %.2f s", ReelTime.seconds(animation.inDuration))
            },
            note: { free() ? nil : Self.wordStyleNote },
            reset: { binding.apply("Animation", text: TextPatch(animation: .some(nil))) },
            defaultExpanded: false,
            rows: [
                inspectorPopupRow(
                    "Reveal", binding, name: "Text Animation", items: items,
                    read: {
                        guard let kind = binding.textProps.animation?.kind else { return 0 }
                        return (kinds.firstIndex(of: kind) ?? 0) + 1
                    },
                    ops: { index in
                        guard index > 0, kinds.indices.contains(index - 1) else {
                            return binding.ops(text: TextPatch(animation: .some(nil)))
                        }
                        // The durations as they stand: switching the reveal
                        // must not reset the timing the user chose for it.
                        var a = current()
                        a.kind = kinds[index - 1]
                        return ops(a)
                    },
                    mixed: { binding.mixedText { $0.animation?.kind } }, enabled: free),
                inspectorValueRow(
                    "In", binding, name: "Animation In", unit: " s", decimals: 2, min: 0, max: 10,
                    quick: [0, 0.25, 0.5, 1, 2],
                    read: { ReelTime.seconds(current().inDuration) },
                    ops: { value in
                        var a = current()
                        a.inDuration = binding.frameTicks(seconds: value)
                        return ops(a)
                    },
                    mixed: { binding.mixedText { $0.animation?.inDuration } },
                    enabled: { on() && free() }),
                inspectorValueRow(
                    "Out", binding, name: "Animation Out", unit: " s", decimals: 2, min: 0,
                    max: 10, quick: [0, 0.25, 0.5, 1, 2],
                    read: { ReelTime.seconds(current().outDuration) },
                    ops: { value in
                        var a = current()
                        a.outDuration = binding.frameTicks(seconds: value)
                        return ops(a)
                    },
                    mixed: { binding.mixedText { $0.animation?.outDuration } },
                    enabled: { on() && free() }),
            ])
    }

    // MARK: Presets

    /// The four one-click looks of §4.3. A preset is two patches — the face
    /// and backdrop (text) plus where the box sits (video) — committed as ONE
    /// undo step, and it routes through the binding like everything else, so
    /// applying one inside an action sets that action's end state.
    func presetSection() -> InspectorSection {
        var buttons: [NSView] = []
        for preset in TextPreset.all {
            buttons.append(
                OptionButtonControl(
                    title: preset.name,
                    action: { [weak self] in self?.apply(preset) },
                    enabled: { true }, onEdit: {}))
        }
        return InspectorSection(
            id: "text.presets", title: "Presets",
            defaultExpanded: false,
            rows: [
                inspectorButtonRow(Array(buttons.prefix(2))),
                inspectorButtonRow(Array(buttons.dropFirst(2))),
            ])
    }

    private func apply(_ preset: TextPreset) {
        let canvas = binding.canvas
        let patches = preset.patches(on: CGSize(width: canvas.width, height: canvas.height))
        binding.apply(
            preset.name, binding.ops(text: patches.text) + binding.ops(video: patches.video))
    }
}

// MARK: - Presets

/// One text preset (§4.3). Sizes and positions are FRACTIONS of the canvas so
/// a preset means the same thing on a 4K canvas as on a vertical one: a size
/// of the canvas's SHORT side, a position of its width and height (spec §11
/// VR-41), so a tall canvas gets the line height a wide one has.
struct TextPreset {
    let name: String
    let font: String
    let sizeFraction: Double
    let xFraction: Double
    let yFraction: Double
    let align: String
    let backdrop: BackdropProps?
    /// Of H, on a canvas taller than wide, in place of `yFraction` (the Caption
    /// row's 0.25, VR-41); nil keeps `yFraction` on every canvas.
    var tallYFraction: Double? = nil

    /// The font size on `canvas`: `sizeFraction` of `min(W, H)`. On a canvas at
    /// least as wide as tall that is H, so the old `H × sizeFraction` is kept to the bit.
    func size(on canvas: CGSize) -> Double {
        (sizeFraction * Double(min(canvas.width, canvas.height))).rounded()
    }

    /// Where the box's centre sits on `canvas`.
    func position(on canvas: CGSize) -> (x: Double, y: Double) {
        let y = canvas.height > canvas.width ? tallYFraction ?? yFraction : yFraction
        return (xFraction * Double(canvas.width), y * Double(canvas.height))
    }

    /// Text ▸ Presets' two patches: the face, size, alignment and backdrop, and where the
    /// box sits at full opacity.
    func patches(on canvas: CGSize) -> (text: TextPatch, video: VideoPatch) {
        let at = position(on: canvas)
        return (
            TextPatch(
                font: font, size: size(on: canvas), align: align, valign: "middle",
                backdrop: .some(backdrop)),
            VideoPatch(x: at.x, y: at.y, opacity: 1)
        )
    }

    static let all: [TextPreset] = [
        TextPreset(
            name: "Title", font: "SourceSans3-Bold", sizeFraction: 0.09, xFraction: 0,
            yFraction: 0, align: "center", backdrop: nil),
        TextPreset(
            name: "Subtitle", font: "SourceSans3-SemiBold", sizeFraction: 0.05, xFraction: 0,
            yFraction: 0.18, align: "center", backdrop: nil),
        TextPreset(
            name: "Lower Third", font: "SourceSans3-SemiBold", sizeFraction: 0.045,
            xFraction: -0.2, yFraction: 0.28, align: "left",
            backdrop: BackdropProps(color: [0, 0, 0, 0.55], padding: 18, radius: 6)),
        TextPreset(
            name: "Caption", font: "SourceSans3-Regular", sizeFraction: 0.035, xFraction: 0,
            yFraction: 0.38, align: "center",
            backdrop: BackdropProps(color: [0, 0, 0, 0.6], padding: 12, radius: 8),
            tallYFraction: 0.25),
    ]
}

// MARK: - Faces

/// The model's one font string ↔ the panel's family + style pair.
///
/// Everything here tolerates a name this machine has no font for: a project
/// carries PostScript names, and the Text tab still has to open (and still has
/// to be able to change the face) on a machine missing that family.
enum TextFace {
    /// Installed families, sorted. Read once — `availableFontFamilies` walks
    /// the font registry, and this popup is rebuilt on every selection change.
    static let families: [String] = NSFontManager.shared.availableFontFamilies.sorted()

    /// One member of a family: its PostScript name and the style label.
    struct Member {
        let name: String
        let style: String
    }

    static func members(of family: String) -> [Member] {
        let raw = NSFontManager.shared.availableMembers(ofFontFamily: family) ?? []
        return raw.compactMap { entry in
            guard entry.count >= 2, let name = entry[0] as? String,
                  let style = entry[1] as? String
            else { return nil }
            return Member(name: name, style: style)
        }
    }

    /// The family a stored PostScript name belongs to; the first installed
    /// family when the font is missing, so the popup always has a row.
    static func family(of postScriptName: String) -> String {
        if let font = NSFont(name: postScriptName, size: 12), let family = font.familyName {
            return family
        }
        return families.first ?? "Helvetica"
    }

    /// The style label of a stored name ("SemiBold"), or "Regular".
    static func style(of postScriptName: String) -> String {
        let family = family(of: postScriptName)
        return members(of: family).first { $0.name == postScriptName }?.style ?? "Regular"
    }

    /// The PostScript name for a family plus a style label, keeping the style
    /// across a family change when the new family has one by that name.
    static func postScriptName(family: String, style: String) -> String {
        let list = members(of: family)
        if let match = list.first(where: { $0.style == style }) { return match.name }
        if let regular = list.first(where: { $0.style == "Regular" }) { return regular.name }
        return list.first?.name ?? family
    }
}

import Foundation

/// The typed text patch the op builders send (`set_text`, `add_text_clip`,
/// an action's end patch).
///
/// A pure move out of `ReelCore.swift` (1542 lines, on the ledger), made
/// before format version 9's `case` and `words` could land in it: Swift
/// cannot add a stored property in an extension, so the type had to leave
/// the over-cap file before it could grow. The `dictionary` extensions on
/// `OutlineProps`, `BackdropProps` and `TextAnimation` that it calls stay in
/// `ReelCore.swift` with every other property type's.

/// A sparse patch of text properties. `width` is three-state as well: nil
/// leaves the box alone, `.some(nil)` restores auto-sizing, `.some(w)` fixes
/// the width and wraps.
///
/// `animation` (format version 5) is three-state for the same reason and
/// with one extra trap of its own: it is an OBJECT, so `.some(a)` REPLACES
/// the whole animation rather than merging into it — a key the caller left
/// out of the object arrives as `TextAnimation`'s own default, not as the
/// clip's current value. `AgentCatalog`'s text-patch sentence says so, and
/// app/CLAUDE.md records the general rule for every nested object in a patch.
struct TextPatch: Codable, Equatable {
    var content: String?
    var font: String?
    var size: Double?
    var color: RGBA?
    var align: String?
    var valign: String?
    var lineSpacing: Double?
    var tracking: Double?
    var outline: OutlineProps??
    var backdrop: BackdropProps??
    var width: Double??
    /// LAST, as `animation` is the last key of the model's `TextProps` — the
    /// two orders are read side by side often enough to be worth keeping.
    var animation: TextAnimation??
    /// Format version 9: `case`, a Swift keyword and so `textCase` here, and
    /// `words`, where an EMPTY list is the sentence "this page is no longer
    /// timed" — what a content edit that changes the word count must send in
    /// the same patch, or the core errors (spec §11 W-2). `word_style` has
    /// ONE writer on this side, `CaptionLayout.place` for a word caption
    /// style (road map 8's W4a); the inspector never sets it (W-10). It is
    /// sent whole — `WordStyle.dictionary` writes all eight keys — because the
    /// core deep-merges it over its template.
    var textCase: TextCase?
    var words: [TextWord]?
    var wordStyle: WordStyle?

    private enum CodingKeys: String, CodingKey {
        case content, font, size, color, align, valign, lineSpacing, tracking, outline, backdrop,
            width, animation, words, wordStyle
        case textCase = "case"
    }

    init(
        content: String? = nil, font: String? = nil, size: Double? = nil, color: RGBA? = nil,
        align: String? = nil, valign: String? = nil, lineSpacing: Double? = nil,
        tracking: Double? = nil, outline: OutlineProps?? = nil, backdrop: BackdropProps?? = nil,
        width: Double?? = nil, animation: TextAnimation?? = nil, textCase: TextCase? = nil,
        words: [TextWord]? = nil, wordStyle: WordStyle? = nil
    ) {
        self.content = content
        self.font = font
        self.size = size
        self.color = color
        self.align = align
        self.valign = valign
        self.lineSpacing = lineSpacing
        self.tracking = tracking
        self.outline = outline
        self.backdrop = backdrop
        self.width = width
        self.animation = animation
        self.textCase = textCase
        self.words = words
        self.wordStyle = wordStyle
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        content = c.lenient(.content)
        font = c.lenient(.font)
        size = c.lenient(.size)
        color = c.lenient(.color)
        align = c.lenient(.align)
        valign = c.lenient(.valign)
        lineSpacing = c.lenient(.lineSpacing)
        tracking = c.lenient(.tracking)
        outline = c.nullable(.outline)
        backdrop = c.nullable(.backdrop)
        width = c.nullable(.width)
        animation = c.nullable(.animation)
        textCase = c.lenient(.textCase)
        words = c.lenient(.words)
        wordStyle = c.lenient(.wordStyle)
    }

    var dictionary: [String: Any] {
        var d: [String: Any] = [:]
        if let content = content { d["content"] = content }
        if let font = font { d["font"] = font }
        if let size = size { d["size"] = size }
        if let color = color { d["color"] = color }
        if let align = align { d["align"] = align }
        if let valign = valign { d["valign"] = valign }
        if let lineSpacing = lineSpacing { d["line_spacing"] = lineSpacing }
        if let tracking = tracking { d["tracking"] = tracking }
        d.putNullable("outline", outline) { $0.dictionary }
        d.putNullable("backdrop", backdrop) { $0.dictionary }
        d.putNullable("width", width) { $0 }
        d.putNullable("animation", animation) { $0.dictionary }
        if let textCase = textCase { d["case"] = textCase.rawValue }
        if let words = words { d["words"] = words.map { $0.dictionary } }
        if let wordStyle = wordStyle { d["word_style"] = wordStyle.dictionary }
        return d
    }

    var isEmpty: Bool { dictionary.isEmpty }
}
import Foundation

/// The text group of the read-only mirror (spec §5.2's `text`), and the
/// recipe's account of one text layer's reveal: `TextAnimationKind`,
/// `OutlineProps`, `BackdropProps`, `TextAnimation`, `TextProps` and
/// `RecipeReveal`.
///
/// A pure move out of `ProjectSnapshot.swift` (2516 lines, on the ledger),
/// made before format version 9's three text fields and the recipe's two
/// word keys could land: Swift cannot add a stored property in an
/// extension, so the types had to leave the over-cap file before they could
/// grow. `MotionProps.swift` is the precedent. The decoding rules are
/// `ProjectSnapshot.swift`'s, stated once at its head — `lenient` and the
/// snake-case key strategy included.

/// The three text reveals of spec §4.3 (format version 5), closed at three.
///
/// `model_props.rs` argues the closure: each kind is a distinct drawing
/// routine in `LayerRenderers.renderText` — a prefix of the glyphs, a
/// per-word alpha ramp, a per-line offset and alpha — not a parameter of a
/// shared one, so there is no neutral kind to fall back to the way a
/// filter's `amount` falls back to 0. The core refuses an unknown one at the
/// serde boundary; HERE the lenient decode answers nil instead, which reads
/// as "no animation" and draws the whole text — the failure direction that
/// shows the words rather than hiding them.
///
/// The key decoding strategy converts KEYS and never VALUES, so the two
/// multi-word cases carry their snake_case spelling by hand, as `Curve` and
/// `TransitionKind` do.
enum TextAnimationKind: String, Codable, CaseIterable {
    case typewriter
    case wordFade = "word_fade"
    case lineRise = "line_rise"

    var displayName: String {
        switch self {
        case .typewriter: return "Typewriter"
        case .wordFade: return "Word Fade"
        case .lineRise: return "Line Rise"
        }
    }
}

/// A text outline (stroke), in canvas pixels.
struct OutlineProps: Codable, Equatable {
    var width: Double
    var color: RGBA

    init(width: Double = 2, color: RGBA = [0, 0, 0, 1]) {
        self.width = width
        self.color = color
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        width = c.lenient(.width, 2)
        color = c.lenient(.color, [0, 0, 0, 1])
    }
}

/// The plate drawn behind text.
struct BackdropProps: Codable, Equatable {
    var color: RGBA
    var padding: Double
    var radius: Double

    init(color: RGBA = [0, 0, 0, 0.6], padding: Double = 12, radius: Double = 8) {
        self.color = color
        self.padding = padding
        self.radius = radius
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        color = c.lenient(.color, [0, 0, 0, 0.6])
        padding = c.lenient(.padding, 12)
        radius = c.lenient(.radius, 8)
    }
}

/// How a text layer arrives and how it leaves (format version 5).
///
/// Three keys and no fourth: `in` and `out` are DURATIONS, not times — the
/// reveal runs for `in` from the clip's own first frame and the un-reveal for
/// `out` back from its own last one, either of them 0 for "that end does not
/// happen". `model_props.rs` argues the missing curve field: the shape of the
/// motion is already in the kind, and easing between two arbitrary values is
/// what the action system is for.
///
/// Nothing in the app derives the reveal from THIS. The core turns it into
/// one number per frame and the recipe carries that number
/// (`RecipeReveal`); this type is what the inspector reads and writes, and
/// the recipe deliberately strips it out of the description it hands the
/// renderer so there can only ever be one answer to "how far along is it".
///
/// `in` is a Swift keyword, so the two durations are spelled out here and the
/// model's own key names live in `CodingKeys` — `ClipSource`'s arrangement,
/// for its reason. The key spelling is the contract with
/// `core/src/model_props.rs`'s `#[serde(rename = "in")]`; the property name
/// is this side's business alone.
struct TextAnimation: Codable, Equatable {
    var kind: TextAnimationKind
    /// How long the reveal takes, from the clip's first frame (the model's
    /// `in`).
    var inDuration: Ticks
    /// How long the un-reveal takes, back from the clip's last frame (the
    /// model's `out`).
    var outDuration: Ticks

    /// The core's own default (`TextAnimation::default`): a one-second
    /// typewriter that does not un-reveal. Mirrored rather than derived, so
    /// switching the inspector's popup on writes exactly what the core would
    /// have defaulted to had the key simply appeared.
    init(
        kind: TextAnimationKind = .typewriter, inDuration: Ticks = Ticks(ReelTime.perSecond),
        outDuration: Ticks = 0
    ) {
        self.kind = kind
        self.inDuration = inDuration
        self.outDuration = outDuration
    }

    private enum CodingKeys: String, CodingKey {
        case kind
        case inDuration = "in"
        case outDuration = "out"
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        kind = c.lenient(.kind, TextAnimationKind.typewriter)
        inDuration = c.lenient(.inDuration, Ticks(ReelTime.perSecond))
        outDuration = c.lenient(.outDuration, 0)
    }
}

/// A text clip's description. The model NEVER stores the measured layout
/// size — only `LayerRenderers` knows it, and it reports it to the canvas
/// overlay through a hash-keyed cache (§5.3, §11).
struct TextProps: Codable, Equatable {
    var content: String
    var font: String
    var size: Double
    var color: RGBA
    /// "left" | "center" | "right".
    var align: String
    /// "top" | "middle" | "bottom", within the box.
    var valign: String
    var lineSpacing: Double
    /// Letter spacing, in points.
    var tracking: Double
    var outline: OutlineProps?
    var backdrop: BackdropProps?
    /// Fixed box width in canvas pixels; nil auto-sizes to the content.
    var width: Double?
    /// How the words arrive and leave, or nil for text that is simply there
    /// for the length of its clip (format version 5). LAST, as it is in the
    /// model, and absent from `LayerRenderers.layoutKey` on purpose: an
    /// animation cannot move a glyph, and a per-frame value in that key
    /// would churn the measured-size cache and walk the overlay's handles.
    var animation: TextAnimation?
    /// Format version 9's three word-caption fields, in the model's order
    /// after `animation` (`core/src/model_text.rs`); their types and what
    /// they mean are `WordProps.swift`'s. `case` is a Swift keyword, so the
    /// property is `textCase` and the model's key lives in `CodingKeys`.
    var textCase: TextCase
    var words: [TextWord]
    var wordStyle: WordStyle?

    private enum CodingKeys: String, CodingKey {
        case content, font, size, color, align, valign, lineSpacing, tracking, outline, backdrop,
            width, animation, words, wordStyle
        case textCase = "case"
    }

    init(
        content: String = "", font: String = "SourceSans3-SemiBold", size: Double = 72,
        color: RGBA = [1, 1, 1, 1], align: String = "center", valign: String = "middle",
        lineSpacing: Double = 1, tracking: Double = 0, outline: OutlineProps? = nil,
        backdrop: BackdropProps? = nil, width: Double? = nil, animation: TextAnimation? = nil,
        textCase: TextCase = .asWritten, words: [TextWord] = [], wordStyle: WordStyle? = nil
    ) {
        self.content = content
        self.font = font
        self.size = size
        self.color = color
        self.align = align
        self.valign = valign
        self.lineSpacing = lineSpacing
        self.tracking = tracking
        self.outline = outline
        self.backdrop = backdrop
        self.width = width
        self.animation = animation
        self.textCase = textCase
        self.words = words
        self.wordStyle = wordStyle
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        content = c.lenient(.content, "")
        font = c.lenient(.font, "SourceSans3-SemiBold")
        size = c.lenient(.size, 72)
        color = c.lenient(.color, [1, 1, 1, 1])
        align = c.lenient(.align, "center")
        valign = c.lenient(.valign, "middle")
        lineSpacing = c.lenient(.lineSpacing, 1)
        tracking = c.lenient(.tracking, 0)
        outline = c.lenient(.outline)
        backdrop = c.lenient(.backdrop)
        width = c.lenient(.width)
        animation = c.lenient(.animation)
        textCase = c.lenient(.textCase, TextCase.asWritten)
        words = c.lenient(.words, [])
        wordStyle = c.lenient(.wordStyle)
    }
}

/// A text layer's computed reveal (§7.3): how much of the text is showing at
/// this instant, which way it is going, and which of the three animations is
/// showing it.
///
/// The CORE computes all three, from `text.animation` and the clip's own
/// time, which is what makes a `render_frame` and an export of the same frame
/// agree by construction — they read one recipe. The layer's `hash` covers
/// them, so the texture cache key IS the picture, and the recipe strips
/// `animation` out of the description it carries: this is the renderer's only
/// account of the animation, and there is deliberately no second one.
///
/// Not `Codable`: the keys are SIBLINGS of `hash` and `text` inside the
/// tagged source object rather than a nested object, so `RecipeSourceRef`'s
/// `text` arm reads them through `init(siblingsOf:)` below. Grouping them here
/// is for the renderer's sake, not the wire's.
struct RecipeReveal: Equatable {
    /// 0 (nothing showing) through 1 (all of it), the un-reveal folded in.
    let amount: Double
    /// "in" while the arrival is holding the amount back, "out" once the
    /// departure is, nil with no animation. `RecipeTransition.role`'s shape,
    /// for its reason: one number cannot say which way it is going.
    let phase: String?
    /// Which drawing routine, or nil for a layer with no animation — which
    /// is also what an unreadable or unknown kind decodes to, so a newer
    /// core's fourth reveal draws the whole text rather than the wrong
    /// animation.
    let kind: TextAnimationKind?
    /// How many of a timed page's words have started, 0 to n — the active
    /// token is `word − 1` — or nil for a page that is not word-timed (no
    /// `word_style`, no `words`, or a count mismatch), which draws static.
    /// The core's `recipe_words.rs` computes it (format version 9).
    let word: Int?
    /// 0…1 through the active word's pop, holding 1 once it settles; nil
    /// before the first word or when `active_scale` is 1.
    let wordPop: Double?
    /// The three looks' answers (format version 12, spec §11 W-13), each
    /// 0…1 or nil: how far the pill has slid from token `word − 2` to the
    /// active one; how much of the active word is filled; how far into a
    /// pause's dim the page is. Nil when the style does not ask for it.
    let wordGlide: Double?
    let wordFill: Double?
    let wordDim: Double?

    init(
        amount: Double = 1, phase: String? = nil, kind: TextAnimationKind? = nil,
        word: Int? = nil, wordPop: Double? = nil, wordGlide: Double? = nil,
        wordFill: Double? = nil, wordDim: Double? = nil
    ) {
        self.amount = amount
        self.phase = phase
        self.kind = kind
        self.word = word
        self.wordPop = wordPop
        self.wordGlide = wordGlide
        self.wordFill = wordFill
        self.wordDim = wordDim
    }

    /// A layer with no animation: all of it, all of the time. The core's
    /// `Reveal::WHOLE`, and the fallback for a recipe this build cannot read
    /// — the failure direction that shows the words.
    static let whole = RecipeReveal()

    /// Whether the departure is what is holding the amount back.
    var isLeaving: Bool { phase == "out" }
}

/// The reveal's keys as `RecipeSourceRef`'s `text` arm carries them: SIBLINGS
/// of `hash` and `text` in the tagged source object, read and written here so
/// the over-cap `ProjectSnapshot.swift` holds none of them
/// (`RecipeSourceRef.graphic(from:)` is the pattern).
extension RecipeReveal {
    /// The core writes `reveal_phase`, `reveal_kind`, `word_pop` and the
    /// rest in snake case, which the converter hands over camel-cased: spell
    /// a key the way the converter does or it silently never matches.
    private enum SiblingKeys: String, CodingKey {
        case reveal, revealPhase, revealKind
        case word, wordPop, wordGlide, wordFill, wordDim
    }

    /// The amount falls back to 1 and the kind to nil, so a recipe this
    /// build cannot read draws the whole text rather than none of it.
    init(siblingsOf decoder: Decoder) {
        guard let c = try? decoder.container(keyedBy: SiblingKeys.self) else {
            self = .whole
            return
        }
        self.init(
            amount: c.lenient(.reveal, 1), phase: c.lenient(.revealPhase),
            kind: c.lenient(.revealKind), word: c.lenient(.word),
            wordPop: c.lenient(.wordPop), wordGlide: c.lenient(.wordGlide),
            wordFill: c.lenient(.wordFill), wordDim: c.lenient(.wordDim))
    }

    func encodeSiblings(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: SiblingKeys.self)
        try c.encode(amount, forKey: .reveal)
        try c.encode(phase, forKey: .revealPhase)
        try c.encode(kind, forKey: .revealKind)
        try c.encode(word, forKey: .word)
        try c.encode(wordPop, forKey: .wordPop)
        try c.encode(wordGlide, forKey: .wordGlide)
        try c.encode(wordFill, forKey: .wordFill)
        try c.encode(wordDim, forKey: .wordDim)
    }
}
