import glob
import struct
import sys


def names(path):
    data = open(path, "rb").read()
    count = struct.unpack(">H", data[4:6])[0]
    tables = {}
    for i in range(count):
        tag, _, off, ln = struct.unpack(">4sIII", data[12 + 16 * i:28 + 16 * i])
        tables[tag.decode()] = (off, ln)
    off, _ = tables["name"]
    _, n, so = struct.unpack(">HHH", data[off:off + 6])
    result = {}
    for i in range(n):
        p, e, l, nid, ln, o = struct.unpack(">6H", data[off + 6 + 12 * i:off + 18 + 12 * i])
        raw = data[off + so + o:off + so + o + ln]
        if p == 3:
            result.setdefault(nid, raw.decode("utf-16-be"))
    inst = []
    if "fvar" in tables:
        fo, _ = tables["fvar"]
        _, _, axoff, _, axcount, axsize, icount, isize = struct.unpack(">HHHHHHHH", data[fo:fo + 16])
        for i in range(icount):
            base = fo + axoff + axcount * axsize + i * isize
            sub = struct.unpack(">H", data[base:base + 2])[0]
            inst.append(result.get(sub))
    return result.get(1), result.get(2), result.get(16), result.get(17), result.get(6), inst


for path in sorted(glob.glob(sys.argv[1] + "/*.ttf")):
    print(path.split("/")[-1], names(path))

